class FilesystemSessionStore(SessionStore):
    """Simple example session store that saves sessions in the filesystem like
    PHP does.

    .. versionchanged:: 0.6
       `renew_missing` was added.  Previously this was considered `True`,
       now the default changed to `False` and it can be explicitly
       deactivated.

    :param path: the path to the folder used for storing the sessions.
                 If not provided the default temporary directory is used.
    :param filename_template: a string template used to give the session
                              a filename.  ``%s`` is replaced with the
                              session id.
    :param session_class: The session class to use.  Defaults to
                          :class:`Session`.
    :param renew_missing: set to `True` if you want the store to
                          give the user a new sid if the session was
                          not yet saved.
    """

    def __init__(self, path=None, filename_template='werkzeug_%s.sess',
                 session_class=None, renew_missing=False, mode=0644):
        SessionStore.__init__(self, session_class)
        if path is None:
            path = gettempdir()
        self.path = path
        if isinstance(filename_template, unicode):
            filename_template = filename_template.encode(
                sys.getfilesystemencoding() or 'utf-8')
        assert not filename_template.endswith(_fs_transaction_suffix), \
            'filename templates may not end with %s' % _fs_transaction_suffix
        self.filename_template = filename_template
        self.renew_missing = renew_missing
        self.mode = mode

    def get_session_filename(self, sid):
        if isinstance(sid, unicode):
            sid = sid.encode('utf-8')
        return path.join(self.path, self.filename_template % sid)

    def save(self, session):
        def _dump(filename):
            f = file(filename, 'wb')
            try:
                dump(dict(session), f, HIGHEST_PROTOCOL)
            finally:
                f.close()
        fn = self.get_session_filename(session.sid)
        if os.name == 'posix':
            td, tmp = tempfile.mkstemp(suffix=_fs_transaction_suffix,
                                       dir=self.path)
            _dump(tmp)
            try:
                os.rename(tmp, fn)
            except (IOError, OSError):
                pass
            os.chmod(fn, self.mode)
        else:
            _dump(fn)
